class Document {
  status: 'draft'|'published'|'archived' = 'draft';

  publish() {
    if (this.status === 'draft') { this.status = 'published'; }
    else if (this.status === 'archived') { throw new Error('cannot publish archived'); }
  }

  archive() {
    if (this.status === 'published') { this.status = 'archived'; }
  }
}

