// Version A: single class with switch-based behavior
class ConnectionA {
  state: 'disconnected'|'connecting'|'connected' = 'disconnected';
  send(data: string) {
    switch (this.state) {
      case 'connected': /* send immediately */ break;
      case 'connecting': /* queue */ break;
      default: /* error */ break;
    }
  }
}

// Version B: separate state objects with a shared interface
interface ConnState { send(ctx: ConnectionB, data: string): void }
class Connected implements ConnState { send(ctx: ConnectionB, data: string) { /* send */ } }
class ConnectionB { state: ConnState = new Connected(); send(data: string) { this.state.send(this, data); } }
